from datetime import date

from src.settle import settlement_date


def test_plain_week():
    assert settlement_date(date(2024, 3, 12)) == date(2024, 3, 14)


def test_over_a_weekend():
    assert settlement_date(date(2024, 3, 14)) == date(2024, 3, 18)


def test_lands_on_a_holiday():
    # the market is closed on 2024-05-06
    assert settlement_date(date(2024, 5, 2)) == date(2024, 5, 7)


def test_holiday_inside_the_period():
    # the market is closed on 2024-03-29, so T+2 should be 2 April
    assert settlement_date(date(2024, 3, 28)) == date(2024, 4, 2)
